package com.bitewise.controller;
import com.bitewise.dto.ProductDtos.*; import com.bitewise.service.ProductService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/products") public class ProductController {private final ProductService s; public ProductController(ProductService s){this.s=s;} @GetMapping public List<ProductResponse> products(){return s.products();} @PostMapping public ProductResponse add(@Valid @RequestBody ProductRequest r){return s.add(r);} @PutMapping("/{id}") public ProductResponse update(@PathVariable UUID id,@Valid @RequestBody ProductRequest r){return s.update(id,r);} @DeleteMapping("/{id}") public void delete(@PathVariable UUID id){s.delete(id);} @GetMapping("/categories") public List<CategoryResponse> categories(){return s.categories();} @PostMapping("/categories") public CategoryResponse addCategory(@Valid @RequestBody CategoryRequest r){return s.addCategory(r);} }
